:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-avatar: #0f3460;
  --bg-stat-wrap: #0f3460;
  --bg-footer: #16213e;
  --accent-primary: #e94560;
  --accent-secondary: #f5a623;
  --accent-green: #4caf82;
  --accent-blue: #4a9eff;
  --text-primary: #ffffff;
  --text-secondary: #a0aec0;
  --text-muted: #5a6a7e;
  --bar-matches: #4a9eff;
  --bar-winrate: #4caf82;
  --bar-kd: #e94560;
  --bar-acc: #f5a623;
  --badge-mvp-bg: #e94560;
  --badge-streak-bg: #f5a623;
  --badge-top-bg: #4caf82;
  --badge-text: #ffffff;
  --rank-bg: #e94560;
  --player-tag-bg: #4a9eff;
  --border-color: #2a2a4a;
  --divider-color: #2a2a4a;
}

.controller-card {
  width: 500px;
  background: var(--bg-card);
  border-radius: 16px;
  border: 2px solid var(--border-color);
  overflow: hidden;
  margin: 0 auto;
}

.card-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 2px solid var(--border-color);
}

.player-tag {
  background: var(--player-tag-bg);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 800;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.header-info {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.card-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 2px;
}

.card-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  margin-top: 1px;
}

.rank-badge {
  background: var(--rank-bg);
  color: var(--badge-text);
  font-size: 15px;
  font-weight: 800;
  padding: 4px 12px;
  border-radius: 20px;
}

.card-body {
  display: flex;
  gap: 0;
  padding: 16px;
}

.avatar-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 110px;
  flex-shrink: 0;
  padding-right: 16px;
  border-right: 2px solid var(--border-color);
}

.avatar {
  width: 72px;
  height: 72px;
  background: var(--bg-avatar);
  border-radius: 50%;
  border: 3px solid var(--accent-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar-icon {
  font-size: 32px;
}

.username {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.level-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.level-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 1px;
}

.level-value {
  font-size: 22px;
  font-weight: 800;
  color: var(--accent-secondary);
  line-height: 1;
}

.stats-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-left: 16px;
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  width: 62px;
  flex-shrink: 0;
}

.stat-bar-wrap {
  flex: 1;
  height: 8px;
  background: var(--bg-stat-wrap);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
}

.stat-bar {
  height: 100%;
  border-radius: 4px;
}

.bar-matches { background: var(--bar-matches); width: 88%; }
.bar-winrate { background: var(--bar-winrate); width: 74%; }
.bar-kd      { background: var(--bar-kd);      width: 76%; }
.bar-acc     { background: var(--bar-acc);     width: 61%; }

.stat-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  width: 36px;
  text-align: right;
  flex-shrink: 0;
}

.badges-row {
  display: flex;
  gap: 6px;
  margin-top: 4px;
}

.badge {
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 10px;
  color: var(--badge-text);
}

.badge-mvp    { background: var(--badge-mvp-bg); }
.badge-streak { background: var(--badge-streak-bg); color: #1a1a2e; }
.badge-top    { background: var(--badge-top-bg); }

.card-footer {
  background: var(--bg-footer);
  border-top: 2px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
}

.footer-item {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.divider {
  width: 1px;
  height: 16px;
  background: var(--divider-color);
}
